import torch
import torch.nn as nn

class ProgressiveColumn(nn.Module):
    """Single task column with lateral connections from prev columns"""
    def __init__(self, input_dim, hidden_dim, n_prev_columns=0):
        super().__init__()
        self.layers = nn.ModuleList([
            nn.Linear(input_dim, hidden_dim),
            nn.Linear(hidden_dim, hidden_dim)
        ])
        # Lateral adapters from previous columns
        self.lateral_adapters = nn.ModuleList([
            nn.ModuleList([nn.Linear(hidden_dim, hidden_dim) for _ in range(len(self.layers))])
            for _ in range(n_prev_columns)
        ])
        self.n_prev = n_prev_columns

    def forward(self, x, prev_activations=None):
        """Forward with lateral connections: h_i^k = σ(W_i^k x + Σ U_i^{k:j} h_{i-1}^j)"""
        activations = []
        h = x
        for layer_idx, layer in enumerate(self.layers):
            h = layer(h)
            # Add lateral connections from previous columns
            if prev_activations is not None:
                for col_idx in range(self.n_prev):
                    if layer_idx < len(prev_activations[col_idx]):
                        h = h + self.lateral_adapters[col_idx][layer_idx](prev_activations[col_idx][layer_idx])
            h = torch.relu(h)
            activations.append(h)
        return h, activations

class ProgressiveNeuralNetwork(nn.Module):
    """Progressive NN: Add new column per task, freeze old columns"""
    def __init__(self, input_dim, hidden_dim, n_classes):
        super().__init__()
        self.columns = nn.ModuleList()
        self.heads = nn.ModuleList()
        self.input_dim = input_dim
        self.hidden_dim = hidden_dim
        self.n_classes = n_classes

    def add_task(self):
        """Add new column for new task"""
        new_column = ProgressiveColumn(self.input_dim, self.hidden_dim, n_prev_columns=len(self.columns))
        new_head = nn.Linear(self.hidden_dim, self.n_classes)
        self.columns.append(new_column)
        self.heads.append(new_head)
        # Freeze all previous columns
        for col in self.columns[:-1]:
            for param in col.parameters():
                param.requires_grad = False

    def forward(self, x, task_id):
        """Forward through all columns up to task_id"""
        all_activations = []
        for col_idx in range(task_id + 1):
            if col_idx == 0:
                h, acts = self.columns[col_idx](x, prev_activations=None)
            else:
                h, acts = self.columns[col_idx](x, prev_activations=all_activations)
            all_activations.append(acts)
        # Use head of current task
        return self.heads[task_id](h)

# Usage: Continual learning without forgetting (capacity grows)
